CREATE TABLE IF NOT EXISTS CX_MEMORY_TIME_FACTS (VERSION_ID VARCHAR(128) PRIMARY KEY REFERENCES CX_MEMORY_VERSIONS(VERSION_ID), EVENT_AT TIMESTAMP, EVENT_TIME_TEXT VARCHAR(128), EVENT_TIME_STATE VARCHAR(24) NOT NULL CHECK(EVENT_TIME_STATE IN ('KNOWN','UNKNOWN','UNKNOWN_OFFSET')), OBSERVED_AT TIMESTAMP NOT NULL, APPLIES_FROM TIMESTAMP, APPLIES_UNTIL TIMESTAMP, CORRECTS_VERSION_ID VARCHAR(128) REFERENCES CX_MEMORY_VERSIONS(VERSION_ID), CORRECTION_SCOPE VARCHAR(1000), CONTENT_DIGEST VARCHAR(64) NOT NULL, CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), INGESTED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CHECK(APPLIES_UNTIL IS NULL OR APPLIES_FROM IS NULL OR APPLIES_UNTIL>APPLIES_FROM), CHECK((EVENT_TIME_STATE='KNOWN' AND EVENT_AT IS NOT NULL) OR (EVENT_TIME_STATE<>'KNOWN' AND EVENT_AT IS NULL)), CHECK((CORRECTS_VERSION_ID IS NULL AND CORRECTION_SCOPE IS NULL) OR (CORRECTS_VERSION_ID IS NOT NULL AND CORRECTION_SCOPE IS NOT NULL AND APPLIES_FROM IS NOT NULL)));

CREATE TABLE IF NOT EXISTS CX_MEMORY_RECON_PROPOSALS (PROPOSAL_ID VARCHAR(128) PRIMARY KEY, SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), RELATION_KIND VARCHAR(24) NOT NULL CHECK(RELATION_KIND IN ('DUPLICATE','CONTRADICTION','REPLACEMENT','UNRESOLVED')), STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN ('PENDING','UNRESOLVED','APPROVED','REJECTED')), METHOD VARCHAR(128) NOT NULL, POLICY_REVISION VARCHAR(128) NOT NULL, CONFIDENCE DECIMAL(8,7), CONFIDENCE_MEANING VARCHAR(1000) NOT NULL, REASON VARCHAR(1000) NOT NULL, CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(CREATED_BY,IDEMPOTENCY_KEY), CHECK(CONFIDENCE IS NULL OR (CONFIDENCE>=0 AND CONFIDENCE<=1)));

CREATE TABLE IF NOT EXISTS CX_MEMORY_RECON_SOURCES (PROPOSAL_ID VARCHAR(128) NOT NULL REFERENCES CX_MEMORY_RECON_PROPOSALS(PROPOSAL_ID), ITEM_NO INTEGER NOT NULL CHECK(ITEM_NO IN (1,2)), FAMILY_ID VARCHAR(128) NOT NULL REFERENCES CX_MEMORY_FAMILIES(FAMILY_ID), VERSION_ID VARCHAR(128) NOT NULL REFERENCES CX_MEMORY_VERSIONS(VERSION_ID), CONTENT_DIGEST VARCHAR(64) NOT NULL, PRIMARY KEY(PROPOSAL_ID,ITEM_NO), UNIQUE(PROPOSAL_ID,VERSION_ID));

CREATE TABLE IF NOT EXISTS CX_MEMORY_RECON_REVIEWS (PROPOSAL_ID VARCHAR(128) PRIMARY KEY REFERENCES CX_MEMORY_RECON_PROPOSALS(PROPOSAL_ID), REVIEWED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), DECISION VARCHAR(24) NOT NULL CHECK(DECISION IN ('APPROVED','REJECTED')), REASON TEXT NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_MEMORY_RESTORE_REQUESTS (ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, FAMILY_ID VARCHAR(128) NOT NULL REFERENCES CX_MEMORY_FAMILIES(FAMILY_ID), ORIGIN_VERSION_ID VARCHAR(128) NOT NULL REFERENCES CX_MEMORY_VERSIONS(VERSION_ID), RESULT_VERSION_ID VARCHAR(128) NOT NULL REFERENCES CX_MEMORY_VERSIONS(VERSION_ID), REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(ACTOR_ID,IDEMPOTENCY_KEY));

CREATE TABLE IF NOT EXISTS CX_WORK_NOTES (NOTE_ID VARCHAR(128) PRIMARY KEY, WORK_CONTRACT_ID VARCHAR(128) NOT NULL REFERENCES CX_WORK_CONTRACTS(WORK_CONTRACT_ID), SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), OWNER_PRINCIPAL_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), VERSION INTEGER NOT NULL CHECK(VERSION>0), CURRENT_REVISION_NO INTEGER NOT NULL CHECK(CURRENT_REVISION_NO>0), STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN ('ACTIVE','RETIRED')), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_WORK_NOTE_REVISIONS (NOTE_ID VARCHAR(128) NOT NULL REFERENCES CX_WORK_NOTES(NOTE_ID), REVISION_NO INTEGER NOT NULL CHECK(REVISION_NO>0), NOTE_TYPE VARCHAR(24) NOT NULL CHECK(NOTE_TYPE IN ('FINDING','REJECTED_APPROACH','VALIDATION','OPEN_QUESTION','NEXT_ACTION')), TITLE TEXT NOT NULL, BODY_TEXT TEXT NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, EXPIRES_AT TIMESTAMP, CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(NOTE_ID,REVISION_NO));

CREATE TABLE IF NOT EXISTS CX_WORK_NOTE_SOURCES (NOTE_ID VARCHAR(128) NOT NULL, REVISION_NO INTEGER NOT NULL, ITEM_NO INTEGER NOT NULL CHECK(ITEM_NO>0), FAMILY VARCHAR(24) NOT NULL, ENTITY_ID VARCHAR(128) NOT NULL, SOURCE_REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, PRIMARY KEY(NOTE_ID,REVISION_NO,ITEM_NO), FOREIGN KEY(NOTE_ID,REVISION_NO) REFERENCES CX_WORK_NOTE_REVISIONS(NOTE_ID,REVISION_NO));

CREATE TABLE IF NOT EXISTS CX_WORK_NOTE_EVENTS (NOTE_ID VARCHAR(128) NOT NULL REFERENCES CX_WORK_NOTES(NOTE_ID), VERSION INTEGER NOT NULL CHECK(VERSION>0), REVISION_NO INTEGER NOT NULL, OPERATION VARCHAR(24) NOT NULL CHECK(OPERATION IN ('CREATE','REVISE','STATE')), STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN ('ACTIVE','RETIRED')), ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(NOTE_ID,VERSION), FOREIGN KEY(NOTE_ID,REVISION_NO) REFERENCES CX_WORK_NOTE_REVISIONS(NOTE_ID,REVISION_NO));

CREATE TABLE IF NOT EXISTS CX_WORK_NOTE_REQUESTS (ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), OPERATION VARCHAR(24) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, NOTE_ID VARCHAR(128) NOT NULL REFERENCES CX_WORK_NOTES(NOTE_ID), VERSION INTEGER NOT NULL, REVISION_NO INTEGER NOT NULL, PRIMARY KEY(ACTOR_ID,OPERATION,IDEMPOTENCY_KEY), FOREIGN KEY(NOTE_ID,VERSION) REFERENCES CX_WORK_NOTE_EVENTS(NOTE_ID,VERSION));

CREATE TABLE IF NOT EXISTS CX_RETROSPECTIVE_JOBS (JOB_ID VARCHAR(128) PRIMARY KEY, SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), TASK_ID VARCHAR(64) NOT NULL, STEP_ID VARCHAR(128) NOT NULL, CONTINUITY_ID VARCHAR(128) NOT NULL REFERENCES CX_TASK_CONTINUITY_LINKS(CONTINUITY_ID), TRIGGER_KIND VARCHAR(24) NOT NULL CHECK(TRIGGER_KIND IN ('SUCCESS','FAILURE','CORRECTION','FEEDBACK')), TARGET_FAMILY VARCHAR(24) NOT NULL CHECK(TARGET_FAMILY IN ('MEMORY','KNOWLEDGE','EXPERIENCE','SKILL')), REPLACES_ENTITY_ID VARCHAR(128), REPLACES_REVISION_ID VARCHAR(128), REPLACES_DIGEST VARCHAR(64), POLICY_REVISION VARCHAR(128) NOT NULL, PROFILE_ID VARCHAR(128) NOT NULL REFERENCES CX_LLM_PROVIDER_PROFILES(PROFILE_ID), PROFILE_VERSION INTEGER NOT NULL CHECK(PROFILE_VERSION>0), TOKEN_BUDGET INTEGER NOT NULL CHECK(TOKEN_BUDGET BETWEEN 128 AND 32768), STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN ('PENDING','RUNNING','UNOBSERVED','PROPOSED','FAILED')), CANDIDATE_ID VARCHAR(128) REFERENCES CX_ARTIFACT_CANDIDATES(CANDIDATE_ID), CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), REASON VARCHAR(1000) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(CREATED_BY,IDEMPOTENCY_KEY), CHECK((REPLACES_ENTITY_ID IS NULL AND REPLACES_REVISION_ID IS NULL AND REPLACES_DIGEST IS NULL) OR (REPLACES_ENTITY_ID IS NOT NULL AND REPLACES_REVISION_ID IS NOT NULL AND REPLACES_DIGEST IS NOT NULL)));

CREATE TABLE IF NOT EXISTS CX_RETROSPECTIVE_SOURCES (JOB_ID VARCHAR(128) NOT NULL REFERENCES CX_RETROSPECTIVE_JOBS(JOB_ID), ITEM_NO INTEGER NOT NULL CHECK(ITEM_NO>0), FAMILY VARCHAR(24) NOT NULL, ENTITY_ID VARCHAR(128) NOT NULL, SOURCE_REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, PRIMARY KEY(JOB_ID,ITEM_NO));

